const markStaleVulnerabilities = `-- name: MarkStaleVulnerabilities :many
UPDATE snapshot_findings sf
SET resolved_at = NOW()
FROM findings f
WHERE sf.snapshot_id = $1
  AND f.id = sf.finding_id
  AND f.type = $2
  AND sf.resolved_at IS NULL
  AND f.status <> 'resolved'
  AND sf.finding_id NOT IN (SELECT unnest($3::uuid[]))
RETURNING f.primary_identifier_value
`

type MarkStaleVulnerabilitiesParams struct {
	SnapshotID uuid.UUID   `json:"snapshot_id"`
	VulnType   string      `json:"vuln_type"`
	FreshIds   []uuid.UUID `json:"fresh_ids"`
}

// The scan no longer matches these on this snapshot: resolved here, the
// finding's own state untouched. Returns the identifiers so the
// notification dedup ledger can forget them.
func (q *Queries) MarkStaleVulnerabilities(ctx context.Context, arg MarkStaleVulnerabilitiesParams) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, markStaleVulnerabilities, arg.SnapshotID, arg.VulnType, pq.Array(arg.FreshIds))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var primary_identifier_value string
		if err := rows.Scan(&primary_identifier_value); err != nil {
			return nil, err
		}
		items = append(items, primary_identifier_value)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setVulnerabilityReachability = `-- name: SetVulnerabilityReachability :execrows
UPDATE snapshot_findings sf
SET reachability = $2
FROM findings f
WHERE sf.snapshot_id = $1
  AND f.id = sf.finding_id
  AND f.type IN ('dependency', 'malware')
  AND (
    f.primary_identifier_value = ANY($3::text[])
    OR EXISTS (
      SELECT 1 FROM advisories a
      WHERE a.id = f.advisory_id AND a.canonical_id = ANY($3::text[])
    )
    OR EXISTS (
      SELECT 1 FROM advisory_aliases aa
      WHERE aa.advisory_id = f.advisory_id AND aa.alias = ANY($3::text[])
    )
  )
`

type SetVulnerabilityReachabilityParams struct {
	SnapshotID   uuid.UUID        `json:"snapshot_id"`
	Reachability NullReachability `json:"reachability"`
	Identifiers  []string         `json:"identifiers"`
}

// CI-side reachability analysis (govulncheck): match on the human identifier
// or any advisory alias — analyzers speak GO-/CVE-/GHSA- interchangeably.
func (q *Queries) SetVulnerabilityReachability(ctx context.Context, arg SetVulnerabilityReachabilityParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setVulnerabilityReachability, arg.SnapshotID, arg.Reachability, pq.Array(arg.Identifiers))
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const setVulnerabilityReachabilityByIDs = `-- name: SetVulnerabilityReachabilityByIDs :execrows
UPDATE snapshot_findings
SET reachability = $1
WHERE snapshot_id = $2 AND finding_id = ANY($3::uuid[])
`

type SetVulnerabilityReachabilityByIDsParams struct {
	Reachability NullReachability `json:"reachability"`
	SnapshotID   uuid.UUID        `json:"snapshot_id"`
	Ids          []uuid.UUID      `json:"ids"`
}

func (q *Queries) SetVulnerabilityReachabilityByIDs(ctx context.Context, arg SetVulnerabilityReachabilityByIDsParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setVulnerabilityReachabilityByIDs, arg.Reachability, arg.SnapshotID, pq.Array(arg.Ids))
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateVulnerabilityStatus = `-- name: UpdateVulnerabilityStatus :one
UPDATE findings
SET status = $1::vulnerability_status,
    state_comment = $2,
    resolved_at = CASE WHEN $1::vulnerability_status = 'resolved' THEN NOW() ELSE resolved_at END,
    resolved_by = CASE WHEN $1::vulnerability_status = 'resolved' THEN $3 ELSE resolved_by END,
    updated_at = NOW()
WHERE id = $4
RETURNING id, org_id, repo_id, type, fingerprint, title, description, primary_identifier_kind, primary_identifier_value, severity, severity_override_reason, severity_override_by, cvss_version, cvss_vector, rated_by, status, state_comment, resolved_at, resolved_by, due_date, present_on_default_branch, resolved_on_default_branch, scanner_name, scanner_vendor, scanner_version, scanner_external_id, file_path, start_line, end_line, location_hash, component_id, component_name, component_version, component_purl, ecosystem, advisory_id, affected_range_id, language, solution, has_remediation, remediation_link, secret_type, secret_hash, commit_sha, author_email, verified, created_by, metadata, rule_ref_id, origin, origin_api_key_id, origin_token_name, origin_owner_type, origin_owner_id, created_at, updated_at, first_seen_at, last_seen_at
`

type UpdateVulnerabilityStatusParams struct {
	Status       string         `json:"status"`
	StateComment sql.NullString `json:"state_comment"`
	ResolvedBy   uuid.NullUUID  `json:"resolved_by"`
	ID           uuid.UUID      `json:"id"`
}

// Triage state lives on the finding, for every snapshot that carries it.
